import time, math
from rob import *

def d5val(n=6):
    v=[]
    for _ in range(n):
        try: v.append(float(rd('d5')))
        except: pass
        time.sleep(0.08)
    return sum(v)/len(v)

def rot_to(tgt, tol=6, tmax=12):
    t0=time.time()
    while time.time()-t0<tmax:
        h=heading()
        err=(tgt-h+180)%360-180
        if abs(err)<tol:
            stop(); time.sleep(0.2)
            h=heading(); err=(tgt-h+180)%360-180
            if abs(err)<tol: return True
            continue
        s=max(6,min(14,abs(err)*0.5))
        if err>0: motors(s,-s)
        else: motors(-s,s)
        time.sleep(0.08)
    stop(); return False

def front(): return ranges()[2]

def drive(dist_stop=0.35, tmax=8):
    """drive forward until front<dist_stop or stuck; returns (moved, reason)"""
    t0=time.time(); last=front(); lastt=t0; moved=0.0
    motors(9,9)
    while time.time()-t0<tmax:
        r=ranges()
        f=r[2]
        if f>0:
            if f<dist_stop: stop(); return moved,'wall'
            if f<last-0.05: moved+=last-f; last=f; lastt=time.time()
            elif f>last+0.3: last=f  # opened up
        # steering: keep sides balanced (beams 1,3 = +-22.5deg)
        l,rr=r[1],r[3]
        if l>0 and rr>0 and min(l,rr)<0.35:
            if l<rr: motors(11,7)
            else: motors(7,11)
        else: motors(9,9)
        if time.time()-lastt>2.0:
            stop(); return moved,'stuck'
        time.sleep(0.1)
    stop(); return moved,'time'

def unstick():
    motors(-9,-9); time.sleep(0.8); stop(); time.sleep(0.2)
    motors(10,-10); time.sleep(0.3); stop(); time.sleep(0.2)
